/** A malformed operator config is deferred only so doctor can report it; execution must still fail closed. */
export function operatorConfigLoadError(): Error | undefined {
  return operatorJsonOperationPolicyError;
}

/**
 * Settings a repository's .env may choose for itself: which endpoint, model and endpoint key to use (a cloud destination
 * still needs the operator's authorization, and the key is bound to that endpoint's origin), task classes, budgets and
 * reasoning effort. Everything else is operator authority, including cloud provider keys and selection.
 */
const PROJECT_ENV_KEYS = new Set([
  "LOCAL_LLM_ENDPOINT",
  "LOCAL_LLM_MODEL",
  // The project's own key for the project's own endpoint: credential binding sends it only to that origin.
  "LOCAL_LLM_API_KEY",
  "LOCAL_LLM_TASK_CLASS",
  "PLANNER_LLM_ENDPOINT",
  "PLANNER_LLM_MODEL",
  "PLANNER_TASK_CLASS",
  "CODER_LLM_ENDPOINT",
  "CODER_LLM_MODEL",
  "NEXUS_TASK_CLASS",
  "NEXUS_CONTINUATION",
  "NEXUS_MAX_TOTAL_STEPS",
  "NEXUS_MAX_TURN_MINUTES",
  "NEXUS_STAGNATION_STEPS",
  "NEXUS_VERIFIER_TIMEOUT_SECS",
  "NEXUS_REASONING_EFFORT",
  "NEXUS_STRICT_TOKEN_COUNT",
  "NEXUS_CONTEXT_LIMIT",
]);

export function isProjectEnvKey(key: string): boolean {
  return PROJECT_ENV_KEYS.has(key) || /^NEXUS_PROJECT_[A-Z0-9_]+$/.test(key);
}

let projectEnvSettings: Record<string, string> = {};
let projectEnvIgnored: string[] = [];

/**
 * Resolves an effective configuration setting across layers:
 * 1. Operator shell environment (highest non-flag authority)
 * 2. Allowlisted project .env setting (per-project overrides of global config.env and defaults; never touches process.env)
 * 3. Global user config (~/.config/nexus/config.env)
 * 4. Base process environment / install defaults
 */
export function effectiveSetting(key: string): string | undefined {
  const shellVal = shellEnvironment[key]?.trim();
  if (shellVal) return shellVal;
  if (isProjectEnvKey(key) && projectEnvSettings[key] !== undefined) {
    return projectEnvSettings[key];
  }
  const configVal = userConfigFile[key]?.trim();
  if (configVal) return configVal;
  return (process.env[key]?.trim() || undefined);
}

export function projectSetting(key: string): string | undefined {
  return projectEnvSettings[key];
}

/**
 * Runs `build` with the per-project `.env` layer switched off. For work whose destination must be the operator's choice
 * although the process runs inside a repository an agent can write (`nexus worktree merge --ai-message` from inside the
 * worktree): a project `.env` there could name the endpoint a diff is sent to.
 */
export function withoutProjectEnvironment<T>(build: () => T): T {
  const saved = projectEnvSettings;
  projectEnvSettings = {};
  try { return build(); } finally { projectEnvSettings = saved; }
}

/** Persist non-secret appliance selection in the operator config without following symlinks or storing API keys. */
export function saveLocalEndpointSettings(endpoint: string, model?: string): void {
  if (!endpoint || /[\r\n\0]/.test(endpoint) || (model !== undefined && (!model || /[\r\n\0]/.test(model)))) {
    throw new Error("The local endpoint and any selected model must be non-empty single-line values.");
  }
  const configDir = path.join(credentialStorageHome(), ".config", "nexus");
  const configFile = path.join(configDir, "config.env");
  const ensureDirectory = (dir: string) => {
    try {
      const stat = fs.lstatSync(dir);
      if (stat.isSymbolicLink() || !stat.isDirectory()) throw new Error("The Nexus configuration path is not a safe directory.");
    } catch (error: any) {
      if (error?.code !== "ENOENT") throw error;
      fs.mkdirSync(dir, { mode: 0o700 });
    }
  };
  ensureDirectory(path.dirname(configDir));
  ensureDirectory(configDir);
  let existing = "";
  try {
    const stat = fs.lstatSync(configFile);
    if (stat.isSymbolicLink() || !stat.isFile()) throw new Error("The Nexus config.env path is not a regular file.");
    existing = fs.readFileSync(configFile, "utf8");
  } catch (error: any) {
    if (error?.code !== "ENOENT") throw error;
  }
  const existingSettings = parseDotenv(existing);
  const previousEndpoint = existingSettings.LOCAL_LLM_ENDPOINT ?? operatorSetting("LOCAL_LLM_ENDPOINT");
  const existingCredentialOrigin = existingSettings.LOCAL_LLM_CREDENTIAL_ORIGIN ?? operatorSetting("LOCAL_LLM_CREDENTIAL_ORIGIN");
  if (existingCredentialOrigin && !originOf(existingCredentialOrigin)) {
    throw new Error("The existing local credential origin is invalid; repair it before changing the endpoint.");
  }
  const previousOrigin = originOf(previousEndpoint);
  const nextOrigin = originOf(endpoint);
  // Keep legacy LOCAL_LLM_API_KEY and gateway-token credentials bound to the endpoint they belonged to before
  // the user changed the selection. New endpoint keys are stored separately by exact origin.
  const preserveCredentialOrigin = !existingCredentialOrigin && previousOrigin && nextOrigin && previousOrigin !== nextOrigin
    ? previousOrigin
    : undefined;
  const keys = new Set(model === undefined ? ["LOCAL_LLM_ENDPOINT"] : ["LOCAL_LLM_ENDPOINT", "LOCAL_LLM_MODEL"]);
  if (preserveCredentialOrigin) keys.add("LOCAL_LLM_CREDENTIAL_ORIGIN");
  const retained = existing.split(/\r?\n/).filter((line) => {
    const match = /^\s*(?:export\s+)?([A-Z0-9_]+)\s*=/.exec(line);
    return !match || !keys.has(match[1]);
  }).filter((line, index, lines) => line !== "" || index < lines.length - 1);
  const values = [`LOCAL_LLM_ENDPOINT=${JSON.stringify(endpoint)}`];
  if (model !== undefined) values.push(`LOCAL_LLM_MODEL=${JSON.stringify(model)}`);
    execFileSync("mkfifo", [path.join(dir, ".env")]);
    process.chdir(dir);
    loadEnvironment(); // a blocking read would hang here; the test then never finishes
    assert.equal(projectSetting("LOCAL_LLM_MODEL"), undefined, "nothing came from the FIFO");
  } finally {
    process.chdir(previous);
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

